<script setup>
import {ref,onUnmounted,watch,computed} from 'vue';import axios from 'axios';import {Head,Link,useForm,router} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({users:Object,search:String,type:String,exam_rounds:{type:Array,default:()=>[]},exams:{type:Array,default:()=>[]},today:String});const {context,base,page}=useExamContext();const student=computed(()=>props.type==='student');const open=ref(false),editing=ref(null),action=ref(null),query=ref(props.search||'');let timeout;watch(query,value=>{clearTimeout(timeout);timeout=setTimeout(()=>router.get(base.value+'/users',{search:value,type:props.type},{preserveState:true,replace:true}),350);});onUnmounted(()=>clearTimeout(timeout));
const form=useForm({name:'',email:'',password:'',role:'admin',is_active:true,managed_tracks:['toeic'],exam_round_id:''});const roles={admin:'Quản trị viên',teacher:'Giáo viên',student:'Thí sinh'};
function show(user=null){editing.value=user;form.exam_round_id='';form.clearErrors();Object.assign(form,user?{name:user.name,email:user.email,password:'',role:user.role,is_active:user.is_active,managed_tracks:user.managed_tracks||['toeic']}:{name:'',email:'',password:student.value?'123456':'',role:student.value?'student':'admin',is_active:true,managed_tracks:['toeic']});open.value=true;}
function save(){form.submit(editing.value?'put':'post',base.value+'/users'+(editing.value?'/'+editing.value.id:''),{onSuccess:()=>{open.value=false;form.reset('password');}});}
function toggle(user){action.value={url:base.value+'/users/'+user.id,method:'put',data:{name:user.name,role:user.role,is_active:!user.is_active},title:user.is_active?'Khóa tài khoản':'Mở khóa tài khoản',message:`${user.is_active?'Khóa':'Mở khóa'} tài khoản ${user.email}?`,button:'Xác nhận'};}
const roundOpen=ref(false);
const roundForm=useForm({name:'',exam_id:'',exam_date:props.today,access_mode:'day',session_name:'',start_time:'08:00',end_time:'10:00',max_attempts:1});
const roundLabel=round=>round.name+' · '+round.exam.title+' · '+round.exam_date.slice(0,10)+' · '+round.max_attempts+' lượt';
function showRound(){roundForm.reset();roundForm.clearErrors();roundOpen.value=true;}
function saveRound(){const known=new Set(props.exam_rounds.map(round=>round.id));roundForm.post(base.value+'/exam-rounds',{onSuccess:()=>{roundOpen.value=false;const added=props.exam_rounds.find(round=>!known.has(round.id));if(added)form.exam_round_id=added.id;}});}
const assigning=ref(null);
const assignment=useForm({name:'',role:'student',is_active:true,exam_round_id:''});
function showAssignment(user){assigning.value=user;assignment.clearErrors();Object.assign(assignment,{name:user.name,role:user.role,is_active:user.is_active,exam_round_id:''});}
function saveAssignment(){assignment.put(base.value+'/users/'+assigning.value.id,{onSuccess:()=>assigning.value=null});}
const importOpen=ref(false),importPreview=ref(null),previewBusy=ref(false);
const importForm=useForm({file:null,exam_round_id:''});
function showImport(){importForm.reset();importForm.clearErrors();importPreview.value=null;importOpen.value=true;}
function chooseImport(event){importForm.file=event.target.files[0]||null;importPreview.value=null;importForm.clearErrors();}
async function previewImport(){
 importForm.clearErrors();previewBusy.value=true;importPreview.value=null;
 try{const data=new FormData();if(importForm.file)data.append('file',importForm.file);data.append('preview','1');if(importForm.exam_round_id)data.append('exam_round_id',importForm.exam_round_id);const response=await axios.post(base.value+'/users/import',data);importPreview.value=response.data;}
 catch(error){const errors=error.response?.data?.errors;importForm.setError(errors?Object.fromEntries(Object.entries(errors).map(([key,value])=>[key,Array.isArray(value)?value.join('\n'):value])):{file:'Chưa kiểm tra được file. Vui lòng thử lại.'});}
 finally{previewBusy.value=false;}
}
function submitImport(){if(!importPreview.value)return;importForm.post(base.value+'/users/import',{forceFormData:true,onSuccess:()=>{importOpen.value=false;importForm.reset();importPreview.value=null;}});}
</script>
<template><Head :title="student?'Tài khoản thi · '+context.name:'Tài khoản quản trị'"/><AppLayout><div class="page-heading"><div><h1>{{student?'Tài khoản thi '+context.name:'Tài khoản quản trị'}}</h1><p>{{student?'Tài khoản được tạo riêng và chỉ đăng nhập vào phần thi này.':'Quản trị viên dùng chung toàn hệ thống; giáo viên được phân quyền theo phân hệ.'}}</p></div><div class="actions"><button v-if="student" class="secondary" @click="showImport()">Nhập Excel</button><button v-if="student" class="secondary" @click="showRound()">+ Tạo khóa thi</button><button @click="show()">+ Thêm tài khoản</button></div></div><div v-if="student" class="notice">Cổng đăng nhập: <a :href="'/exam/'+context.slug+'/login'" target="_blank" rel="noopener" class="text-link">/exam/{{context.slug}}/login</a>. Tạo tài khoản trước, sau đó bấm “Xếp khóa thi” để chọn khóa. Ngày/ca, đề và số lượt được lấy từ khóa đã chọn.</div><div class="card"><div class="panel-title"><h2>Danh sách tài khoản</h2><Link v-if="student" :href="base+'/exam-accesses'" class="btn secondary">Cấp quyền thi →</Link></div><input v-model="query" :placeholder="student?'Tìm theo họ tên hoặc tên đăng nhập…':'Tìm theo tên hoặc email…'" aria-label="Tìm tài khoản"/><div class="tablewrap"><table><thead><tr><th>Họ tên</th><th>{{student?'Tên đăng nhập':'Email'}}</th><th>{{student?'Phần thi':'Vai trò'}}</th><th v-if="student">Khóa thi</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="user in users.data" :key="user.id"><td>{{user.name}}</td><td>{{user.email}}</td><td>{{student?context.name:roles[user.role]}}<small v-if="user.role==='teacher'" class="cell-meta">{{(user.managed_tracks||['toeic']).map(slug=>page.props.modules.find(module=>module.slug===slug)?.name).join(' · ')}}</small></td><td v-if="student"><template v-for="access in user.exam_accesses?.filter(access=>access.round&&!access.archived)" :key="access.id"><span class="pill">{{access.round.name}}</span> </template><span v-if="!user.exam_accesses?.some(access=>access.round&&!access.archived)" class="muted">Chưa xếp khóa</span><small v-if="user.exam_accesses?.some(access=>access.archived)" class="cell-meta">Lịch sử: {{user.exam_accesses.filter(access=>access.archived).length}} khóa</small></td><td><span class="pill" :class="{inactive:!user.is_active}">{{user.is_active?'Hoạt động':'Đã khóa'}}</span></td><td><div class="actions"><button v-if="student" @click="showAssignment(user)">Xếp khóa thi</button><button class="secondary" @click="show(user)">Sửa / mật khẩu</button><button class="secondary" @click="toggle(user)">{{user.is_active?'Khóa':'Mở khóa'}}</button><button class="secondary" @click="action={url:base+'/users/'+user.id,title:'Xóa tài khoản',message:'Xóa tài khoản '+user.email+'? Tài khoản có lịch sử sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!users.data.length"><td :colspan="student?6:5" class="empty-state">Chưa có tài khoản phù hợp.</td></tr></tbody></table></div><div class="pagination"><Link v-if="users.prev_page_url" :href="users.prev_page_url">← Trước</Link><span>Trang {{users.current_page}} / {{users.last_page}}</span><Link v-if="users.next_page_url" :href="users.next_page_url">Tiếp →</Link></div></div><AppModal :open="open" :title="editing?'Sửa tài khoản':'Thêm tài khoản'" :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><div class="field"><label for="user-name">Họ tên</label><input id="user-name" v-model="form.name" required maxlength="255"/></div><div class="field"><label for="user-email">{{student?'Tên đăng nhập':'Email đăng nhập'}}</label><input id="user-email" v-model="form.email" :type="student?'text':'email'" :placeholder="student?'Ví dụ: TS001':undefined" required :disabled="!!editing" maxlength="255"/></div><div class="field"><label for="user-password">{{editing?'Mật khẩu mới (bỏ trống để giữ nguyên)':(student?'Mật khẩu (mặc định 123456)':'Mật khẩu (ít nhất 12 ký tự)')}}</label><input id="user-password" v-model="form.password" type="password" :minlength="student?4:12" maxlength="128" :required="!editing&&!student" autocomplete="new-password"/><p v-if="student&&!editing" class="info-copy">Để trống mật khẩu để dùng mặc định: <strong>123456</strong>.</p></div><div v-if="!student" class="field"><label for="user-role">Vai trò</label><select id="user-role" v-model="form.role"><option value="admin">Quản trị viên</option><option value="teacher">Giáo viên</option></select></div><div v-if="form.role==='teacher'" class="field"><label>Phân hệ được quản lý</label><div class="inline-options"><label v-for="module in page.props.modules" :key="module.slug"><input v-model="form.managed_tracks" type="checkbox" :value="module.slug"/>{{module.name}}</label></div></div><div v-if="editing" class="field"><label for="user-active">Trạng thái</label><select id="user-active" v-model="form.is_active"><option :value="true">Hoạt động</option><option :value="false">Đã khóa</option></select></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing">Lưu tài khoản</button></div></form></AppModal><ConfirmAction :action="action" @close="action=null"/>
<AppModal :open="roundOpen" title="Tạo khóa thi" :busy="roundForm.processing" @close="roundOpen=false"><form @submit.prevent="saveRound"><FormErrors :errors="roundForm.errors"/><div class="field"><label for="round-name">Tên khóa thi</label><input id="round-name" v-model="roundForm.name" placeholder="Ví dụ: TOEIC tháng 10 - Đợt 1" required maxlength="255"/></div><div class="field"><label for="round-exam">Đề thi (thi toàn bộ đề)</label><select id="round-exam" v-model="roundForm.exam_id" required><option value="" disabled>Chọn đề đã mở</option><option v-for="exam in exams" :key="exam.id" :value="exam.id">{{exam.title}} · {{exam.questions_count}} câu</option></select><p v-if="!exams.length" class="info-copy">Cần mở đề có câu hỏi trước khi tạo khóa thi.</p></div><div class="formgrid"><div class="field"><label for="round-date">Ngày thi</label><input id="round-date" v-model="roundForm.exam_date" type="date" :min="today" required/></div><div class="field"><label for="round-mode">Thời gian thi</label><select id="round-mode" v-model="roundForm.access_mode"><option value="day">Cả ngày</option><option value="session">Theo ca</option></select></div><template v-if="roundForm.access_mode==='session'"><div class="field"><label for="round-session">Tên ca</label><input id="round-session" v-model="roundForm.session_name" required maxlength="255"/></div><div class="field"><label for="round-start">Giờ bắt đầu</label><input id="round-start" v-model="roundForm.start_time" type="time" required/></div><div class="field"><label for="round-end">Giờ kết thúc</label><input id="round-end" v-model="roundForm.end_time" type="time" required/></div></template><div class="field"><label for="round-attempts">Số lượt thi mỗi tài khoản</label><input id="round-attempts" v-model.number="roundForm.max_attempts" type="number" min="1" max="100" required/></div></div><div class="modal-actions"><button type="button" class="secondary" @click="roundOpen=false">Hủy</button><button :disabled="roundForm.processing||!exams.length">Tạo khóa thi</button></div></form></AppModal><AppModal :open="!!assigning" title="Xếp tài khoản vào khóa thi" :busy="assignment.processing" @close="assigning=null"><form @submit.prevent="saveAssignment"><FormErrors :errors="assignment.errors"/><p><strong>{{assigning?.name}}</strong> · {{assigning?.email}}</p><div class="field"><label for="assign-round">Khóa thi</label><select id="assign-round" v-model="assignment.exam_round_id" required><option value="" disabled>Chọn khóa thi còn hiệu lực</option><option v-for="round in exam_rounds" :key="round.id" :value="round.id">{{roundLabel(round)}}</option></select></div><p class="info-copy">Tài khoản được cấp toàn bộ đề, ngày/ca và số lượt của khóa. Lịch sử thi cũ được giữ lại.</p><p v-if="!exam_rounds.length" class="notice">Chưa có khóa thi còn hiệu lực. Hãy tạo khóa thi trước.</p><div class="modal-actions"><button type="button" class="secondary" @click="assigning=null">Hủy</button><button :disabled="assignment.processing||!exam_rounds.length">Xếp vào khóa thi</button></div></form></AppModal><AppModal :open="importOpen" title="Nhập danh sách tài khoản Excel" wide :busy="importForm.processing||previewBusy" @close="importOpen=false"><form @submit.prevent="submitImport"><FormErrors class="excel-import-errors" :errors="importForm.errors"/><p>Tải mẫu, điền danh sách rồi chọn file .xlsx để kiểm tra trước khi nhập. Tối đa 1.000 tài khoản, dung lượng 5 MB.</p><a :href="base+'/users/import-template'" class="btn secondary">Tải file Excel mẫu</a><p class="info-copy">Cột: <strong>ho_ten</strong>, <strong>ten_dang_nhap</strong>, <strong>mat_khau</strong>. Mật khẩu để trống dùng <strong>123456</strong>. Định dạng tên đăng nhập dạng văn bản để giữ số 0 ở đầu. Tài khoản trùng sẽ báo lỗi, không ghi đè tài khoản cũ.</p><div class="field"><label for="import-accounts-file">File danh sách tài khoản</label><input id="import-accounts-file" type="file" accept=".xlsx" required :disabled="importForm.processing||previewBusy" @change="chooseImport"/></div><div class="field"><label for="import-round">Xếp vào khóa thi (tùy chọn)</label><select id="import-round" v-model="importForm.exam_round_id" :disabled="importForm.processing||previewBusy"><option value="">Chỉ tạo tài khoản, xếp khóa sau</option><option v-for="round in exam_rounds" :key="round.id" :value="round.id">{{roundLabel(round)}}</option></select></div><button type="button" class="secondary" :disabled="!importForm.file||previewBusy||importForm.processing" @click="previewImport">{{previewBusy?'Đang kiểm tra…':'Kiểm tra và xem trước'}}</button><div v-if="importPreview" class="section-gap"><p class="notice success">File hợp lệ: {{importPreview.count}} tài khoản. Dưới đây là {{importPreview.rows.length}} dòng đầu.</p><div class="tablewrap"><table><thead><tr><th>Dòng</th><th>Họ tên</th><th>Tên đăng nhập</th></tr></thead><tbody><tr v-for="row in importPreview.rows" :key="row.row"><td>{{row.row}}</td><td>{{row.name}}</td><td>{{row.username}}</td></tr></tbody></table></div></div><div class="modal-actions"><button type="button" class="secondary" :disabled="importForm.processing||previewBusy" @click="importOpen=false">Hủy</button><button :disabled="!importPreview||importForm.processing||previewBusy">{{importForm.processing?'Đang nhập…':'Nhập '+(importPreview?.count||0)+' tài khoản'}}</button></div></form></AppModal></AppLayout></template>
